-- Automation cell (automation), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA automation;

CREATE FUNCTION automation.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE automation.cron_jobs (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    name                     text NOT NULL CHECK (length(name) <= 200 AND length(name) >= 1),
    description              text,
    schedule                 text NOT NULL CHECK (length(schedule) <= 200 AND length(schedule) >= 1),
    job_type                 text NOT NULL CHECK (length(job_type) <= 80 AND length(job_type) >= 1),
    params                   text NOT NULL DEFAULT '{}',
    is_active                boolean NOT NULL DEFAULT true,
    last_run_at              timestamptz,
    next_run_at              timestamptz,
    last_status              text NOT NULL DEFAULT 'pending' CHECK (length(last_status) <= 40),
    retry_count              integer NOT NULL DEFAULT 0 CHECK (retry_count >= 0),
    last_retry_at            timestamptz,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE UNIQUE INDEX cron_jobs_legacy ON automation.cron_jobs (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX cron_jobs_is_active ON automation.cron_jobs (workspace_id, is_active);
CREATE INDEX cron_jobs_job_type ON automation.cron_jobs (workspace_id, job_type);
CREATE INDEX cron_jobs_last_status ON automation.cron_jobs (workspace_id, last_status);
CREATE INDEX cron_jobs_name ON automation.cron_jobs (workspace_id, name);

CREATE TABLE automation.automation_rules (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    name                     text NOT NULL CHECK (length(name) <= 200 AND length(name) >= 1),
    description              text,
    trigger                  text NOT NULL CHECK (length(trigger) >= 1),
    action                   text NOT NULL CHECK (length(action) >= 1),
    project_filter           text CHECK (project_filter IS NULL OR (length(project_filter) <= 200)),
    priority_filter          integer,
    category_filter          text CHECK (category_filter IS NULL OR (length(category_filter) <= 200)),
    is_active                boolean NOT NULL DEFAULT true,
    execution_count          integer NOT NULL DEFAULT 0 CHECK (execution_count >= 0),
    last_executed_at         timestamptz,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE UNIQUE INDEX automation_rules_legacy ON automation.automation_rules (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX automation_rules_is_active ON automation.automation_rules (workspace_id, is_active);

CREATE TABLE automation.workflow_pipelines (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    name                     text NOT NULL CHECK (length(name) <= 200 AND length(name) >= 1),
    description              text,
    steps                    text NOT NULL CHECK (length(steps) >= 1),
    is_active                boolean NOT NULL DEFAULT true,
    run_count                integer NOT NULL DEFAULT 0 CHECK (run_count >= 0),
    last_run_at              timestamptz,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE UNIQUE INDEX workflow_pipelines_legacy ON automation.workflow_pipelines (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX workflow_pipelines_is_active ON automation.workflow_pipelines (workspace_id, is_active);

CREATE TABLE automation.automation_log (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    rule_id                  bigint,
    pipeline_id              bigint,
    action_type              text NOT NULL CHECK (length(action_type) <= 40 AND length(action_type) >= 1),
    description              text NOT NULL CHECK (length(description) >= 1),
    affected_tasks           text,
    affected_count           integer NOT NULL DEFAULT 0 CHECK (affected_count >= 0),
    success                  boolean NOT NULL DEFAULT true,
    error_message            text,
    executed_at              timestamptz,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    FOREIGN KEY (workspace_id, rule_id) REFERENCES automation.automation_rules (workspace_id, id),
    FOREIGN KEY (workspace_id, pipeline_id) REFERENCES automation.workflow_pipelines (workspace_id, id)
);
CREATE UNIQUE INDEX automation_log_legacy ON automation.automation_log (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX automation_log_action_type ON automation.automation_log (workspace_id, action_type);
CREATE INDEX automation_log_pipeline_id ON automation.automation_log (workspace_id, pipeline_id);
CREATE INDEX automation_log_rule_id ON automation.automation_log (workspace_id, rule_id);
CREATE INDEX automation_log_success ON automation.automation_log (workspace_id, success);

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE automation.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('cron-job', 'automation-rule', 'workflow-pipeline', 'automation-log')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE automation.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON automation.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['cron_jobs', 'automation_rules', 'workflow_pipelines', 'automation_log', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE automation.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE automation.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON automation.%I'
                       ' USING (workspace_id = automation.current_workspace())'
                       ' WITH CHECK (workspace_id = automation.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA automation TO automation_api;
GRANT EXECUTE ON FUNCTION automation.current_workspace() TO automation_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON automation.cron_jobs, automation.automation_rules, automation.workflow_pipelines, automation.automation_log TO automation_api;
GRANT USAGE ON SEQUENCE automation.cron_jobs_id_seq, automation.automation_rules_id_seq, automation.workflow_pipelines_id_seq, automation.automation_log_id_seq TO automation_api;
GRANT SELECT, INSERT ON automation.create_keys TO automation_api;
GRANT SELECT, INSERT ON automation.outbox TO automation_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON automation.outbox TO automation_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON automation.outbox TO automation_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA automation TO automation_publisher;
GRANT SELECT ON automation.outbox TO automation_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON automation.outbox TO automation_publisher;
